    // ═══════════════════════════════════════════════════════
    // 🔢 DECIMAL HELPERS
    // ═══════════════════════════════════════════════════════
    function _normalizeTo18(
        uint256 amount,
        uint8 decimals
    ) internal pure returns (uint256) {
        if (decimals == 18) return amount;
        return
            decimals < 18
                ? amount * (10 ** (18 - decimals))
                : amount / (10 ** (decimals - 18));
    }

    function _denormalizeFrom18(
        uint256 amount,
        uint8 decimals
    ) internal pure returns (uint256) {
        if (decimals == 18) return amount;
        return
            decimals < 18
                ? amount / (10 ** (18 - decimals))
                : amount * (10 ** (decimals - 18));
    }

