        userSoldValueUsdt18[msg.sender] = alreadySoldUsdt18 + sellValueUsdt18;
        quoteToken.safeTransfer(msg.sender, actualPayout);
        _updatePrice();

        emit TradeExecuted(
            msg.sender,
            "SELL",
            actualPayout,
            amountTokens,
            amountTokens
